using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
/* Cutting List workspace (owner, 19 November 2026). Beam: upload the beam schedule, set up the beam lines (spans, support widths,
   slab), tick the spans that go into the estimate, then the cutting list, splice zone check, commercial bars and estimate per span
   are generated. Lap lengths come from the Splice, Development & Hooks configurations. Column, foundation and slab lists follow. */
class CuttingListForm:Form {
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 readonly NavigationTabs tabs=new NavigationTabs{Dock=DockStyle.Fill};readonly DataGridView spans=new DataGridView{Dock=DockStyle.Fill};
 readonly DataGridView cutGrid=Output(),spliceGrid=Output(),estimateGrid=Output(),buyGrid=Output();readonly TextBox review=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Font=new Font("Consolas",9.5f)};
 readonly Label status=new Label{Dock=DockStyle.Bottom,Height=30,Padding=new Padding(10,6,0,0)};readonly Label source=new Label{Dock=DockStyle.Top,Height=30,Padding=new Padding(10,6,0,0),Text="Load a beam schedule DXF (formatted by the Beam Formatter) to start."};
 readonly ComboBox config=Combo(260),frame=Combo(300),longest=Combo(90),topExtension=Combo(110);readonly NumericUpDown cover=Number(20,150,40,0),endZone=Number(10,45,25,0),offset=Number(25,150,50,0);readonly TextBox stocks=new TextBox{Width=150,Text="6,7.5,9,10.5,12"};
 readonly Dictionary<string,BeamRow> schedule=new Dictionary<string,BeamRow>(StringComparer.OrdinalIgnoreCase);readonly List<string[]> sources=new List<string[]>();
 readonly Timer debounce=new Timer{Interval=400};bool filling;CutResult last;CutSettings lastSettings;List<CutSpan> lastSpans;string saved="";
 static DataGridView Output(){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells,SelectionMode=DataGridViewSelectionMode.CellSelect};return g;}
 static ComboBox Combo(int width){return new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=width};}
 static NumericUpDown Number(decimal min,decimal max,decimal value,int decimals){return new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Width=90};}
 static void Field(FlowLayoutPanel panel,string label,Control input){var box=new FlowLayoutPanel{FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=true,Margin=new Padding(0,0,16,6)};box.Controls.Add(new Label{Text=label,AutoSize=true,UseMnemonic=false});box.Controls.Add(input);panel.Controls.Add(box);}
 public CuttingListForm(){if(!AccessCodes.CanUseApp(ProgramAccess.ProgramOfWorks))throw new Exception("This app is not included in your current access.");AppBrand.Apply(this);Text="Cutting List";ClientSize=new Size(1360,860);MinimumSize=new Size(1000,640);Font=new Font("Segoe UI",9.5f);StartPosition=FormStartPosition.CenterScreen;
  var beamPage=new TabPage("Beam Cutting List");tabs.TabPages.Add(beamPage);
  var commands=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(8),WrapContents=true};
  Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=36};b.Click+=(s,e)=>{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Beam Cutting List",MessageBoxButtons.OK,MessageBoxIcon.Information);}};commands.Controls.Add(b);};
  button("Load beam schedule DXF",LoadSchedule);button("Save cutting list",Save);button("Open cutting list",Open);button("Print preview",()=>{Calculate();CalculationPreview.Show(this,ReportText());});button("Copy cutting list",()=>{Calculate();Clipboard.SetText(Tsv(cutGrid));});
  var settings=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(10,4,10,4),WrapContents=true};
  foreach(var c in CalculationStore.All())config.Items.Add(c.Name);if(config.Items.Count>0)config.SelectedIndex=0;var preferred=config.Items.Cast<string>().FirstOrDefault(n=>n.Contains("FC28")&&n.Contains("G40/G60"));if(preferred!=null)config.SelectedItem=preferred;
  frame.Items.AddRange(new object[]{"Special moment frame (NSCP 418.6.3.3)","Ordinary frame / non-seismic"});frame.SelectedIndex=0;
  longest.Items.AddRange(new object[]{"6","7.5","9","10.5","12"});longest.SelectedItem="12";topExtension.Items.AddRange(new object[]{"Ln / 3","Ln / 4"});topExtension.SelectedIndex=0;
  Field(settings,"Splice, development & hooks",config);Field(settings,"Splice zones",frame);Field(settings,"Cover (mm)",cover);Field(settings,"Longest bar (m)",longest);Field(settings,"Commercial lengths (m)",stocks);Field(settings,"Stirrup end zone (% of Ln)",endZone);Field(settings,"First stirrup from face (mm)",offset);Field(settings,"Extra top bars past face",topExtension);
  var spanTitle=new Label{Dock=DockStyle.Top,Height=46,Padding=new Padding(10,8,10,0),Text="BEAM LINES - one row per span, in order. Spans of the same line share the line ID; the right support of a span is the left support of the next. Untick \"In estimate\" to leave a span out of the estimate (the cutting list still covers the whole line).",ForeColor=PowTheme.Muted};
  SetupSpans();var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal};/* beam lines above, results below (about 40 / 60) */Shown+=(s0,e0)=>{try{split.SplitterDistance=Math.Max(160,(int)(split.Height*.4));}catch(Exception){}};
  var inputHost=new Panel{Dock=DockStyle.Fill};inputHost.Controls.Add(spans);inputHost.Controls.Add(spanTitle);split.Panel1.Controls.Add(inputHost);
  var results=new NavigationTabs{Dock=DockStyle.Fill};foreach(var pair in new[]{new KeyValuePair<string,Control>("Cutting list",cutGrid),new KeyValuePair<string,Control>("Splice zone check",spliceGrid),new KeyValuePair<string,Control>("Estimate per span",estimateGrid),new KeyValuePair<string,Control>("Commercial bars",buyGrid),new KeyValuePair<string,Control>("Review",review)}){var page=new TabPage(pair.Key);page.Controls.Add(pair.Value);results.TabPages.Add(page);}split.Panel2.Controls.Add(results);
  beamPage.Controls.Add(split);beamPage.Controls.Add(source);beamPage.Controls.Add(settings);beamPage.Controls.Add(commands);
  Controls.Add(tabs);Controls.Add(status);
  debounce.Tick+=(s,e)=>{debounce.Stop();Calculate();};EventHandler changed=(s,e)=>{if(!filling)Schedule();};foreach(var c in new Control[]{config,frame,longest,topExtension})((ComboBox)c).SelectedIndexChanged+=changed;foreach(var c in new[]{cover,endZone,offset})c.ValueChanged+=changed;stocks.TextChanged+=changed;
  FormClosing+=(s,e)=>{if(State()!=saved&&schedule.Count>0){var answer=MessageBox.Show(this,"Save the cutting list before closing?","Beam Cutting List",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)e.Cancel=true;else if(answer==DialogResult.Yes){try{if(!SaveDialog())e.Cancel=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Beam Cutting List");e.Cancel=true;}}}};
  FormClosed+=(s,e)=>debounce.Dispose();
  #if !ADMIN_APP
  var renewal=new AccessRenewal(this);FormClosed+=(s,e)=>renewal.Dispose();
  #endif
 }
 void Schedule(){debounce.Stop();debounce.Start();}
 void SetupSpans(){spans.AllowUserToAddRows=true;spans.AllowUserToDeleteRows=true;spans.RowHeadersVisible=true;spans.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
  spans.Columns.Add("Line","LINE ID");spans.Columns.Add("Span","SPAN");spans.Columns["Span"].ReadOnly=true;var mark=new DataGridViewComboBoxColumn{Name="Mark",HeaderText="BEAM MARK",DisplayStyle=DataGridViewComboBoxDisplayStyle.DropDownButton,FlatStyle=FlatStyle.Flat};spans.Columns.Add(mark);
  foreach(var c in new[]{new[]{"Ln","CLEAR SPAN Ln (m)"},new[]{"Left","LEFT SUPPORT WIDTH (mm)"},new[]{"Right","RIGHT SUPPORT WIDTH (mm)"},new[]{"Slab","SLAB THICKNESS (mm)"},new[]{"Qty","IDENTICAL LINES (first span)"}})spans.Columns.Add(c[0],c[1]);
  spans.Columns.Add(new DataGridViewCheckBoxColumn{Name="Include",HeaderText="IN ESTIMATE"});foreach(DataGridViewColumn c in spans.Columns)if(!c.ReadOnly)c.DefaultCellStyle.BackColor=ModernUi.Input;spans.Columns["Span"].FillWeight=40;spans.Columns["Include"].FillWeight=50;
  spans.DefaultValuesNeeded+=(s,e)=>{var prev=spans.Rows.Cast<DataGridViewRow>().LastOrDefault(r=>!r.IsNewRow);e.Row.Cells["Line"].Value=prev==null?"B1":prev.Cells["Line"].Value;e.Row.Cells["Mark"].Value=prev==null?null:prev.Cells["Mark"].Value;e.Row.Cells["Left"].Value=prev==null?"400":prev.Cells["Right"].Value;e.Row.Cells["Right"].Value=prev==null?"400":prev.Cells["Right"].Value;e.Row.Cells["Slab"].Value=prev==null?"100":prev.Cells["Slab"].Value;e.Row.Cells["Qty"].Value="1";e.Row.Cells["Include"].Value=true;};
  spans.CellValueChanged+=(s,e)=>{if(!filling)Schedule();};spans.RowsRemoved+=(s,e)=>{if(!filling)Schedule();};spans.CurrentCellDirtyStateChanged+=(s,e)=>{if(spans.IsCurrentCellDirty&&spans.CurrentCell is DataGridViewCheckBoxCell)spans.CommitEdit(DataGridViewDataErrorContexts.Commit);};spans.DataError+=(s,e)=>{e.ThrowException=false;};
  RowDeleteAffordance.Attach(spans);GridAppearance.Apply(spans);}
 void LoadSchedule(){using(var d=new OpenFileDialog{Filter="Beam schedule DXF (*.dxf)|*.dxf",Multiselect=true}){if(d.ShowDialog(this)!=DialogResult.OK)return;var files=d.FileNames.Select(path=>{var f=PowSourceFiles.ReadFile(path,"Beam DXF");return new[]{f.Text(),f.Name};}).ToList();AddSources(files,true);}}
 internal void AddSources(IEnumerable<string[]> files,bool replace){var parsed=new List<KeyValuePair<string[],Analysis>>();foreach(var f in files)parsed.Add(new KeyValuePair<string[],Analysis>(f,ManualBeamSchedule.Read(f[0],f[1])));
  var marks=new Dictionary<string,BeamRow>(StringComparer.OrdinalIgnoreCase);if(!replace)foreach(var kv in schedule)marks[kv.Key]=kv.Value;foreach(var kv in parsed)foreach(var row in kv.Value.Source){if(marks.ContainsKey(row.Mark))throw new Exception("Beam mark "+row.Mark+" appears in more than one schedule. Load each mark once.");marks[row.Mark]=row;}
  if(replace)sources.Clear();sources.AddRange(parsed.Select(p=>p.Key));schedule.Clear();foreach(var kv in marks)schedule[kv.Key]=kv.Value;
  var column=(DataGridViewComboBoxColumn)spans.Columns["Mark"];column.Items.Clear();foreach(var m in schedule.Keys.OrderBy(k=>k,StringComparer.OrdinalIgnoreCase))column.Items.Add(m);
  foreach(DataGridViewRow r in spans.Rows)if(!r.IsNewRow&&r.Cells["Mark"].Value!=null&&!schedule.ContainsKey(Convert.ToString(r.Cells["Mark"].Value)))r.Cells["Mark"].Value=null;
  source.Text="Schedule: "+string.Join(", ",sources.Select(s=>s[1]))+" - "+schedule.Count+" beam marks ("+string.Join(", ",schedule.Keys.Take(12))+(schedule.Count>12?", ...":"")+").";Schedule();}
 static string Cell(DataGridViewRow r,string name){return Convert.ToString(r.Cells[name].Value,Inv).Trim();}
 static double Read(string text,string what,int row){double v;if(!double.TryParse(text,NumberStyles.Float,Inv,out v)||double.IsNaN(v)||double.IsInfinity(v))throw new Exception("Row "+row+": enter "+what+" as a number.");return v;}
 List<CutSpan> SpanInputs(){var list=new List<CutSpan>();int index=0;string line=null;int number=0;foreach(DataGridViewRow r in spans.Rows){if(r.IsNewRow)continue;index++;string id=Cell(r,"Line");if(id==""&&Cell(r,"Mark")==""&&Cell(r,"Ln")=="")continue;if(id=="")throw new Exception("Row "+index+": enter the line ID.");
   number=string.Equals(id,line,StringComparison.OrdinalIgnoreCase)?number+1:1;line=id;filling=true;try{r.Cells["Span"].Value=number;}finally{filling=false;}
   int qty;if(!int.TryParse(Cell(r,"Qty")==""?"1":Cell(r,"Qty"),out qty))throw new Exception("Row "+index+": identical lines must be a whole number.");
   list.Add(new CutSpan{Line=id,Mark=Cell(r,"Mark"),Ln=Read(Cell(r,"Ln"),"the clear span",index),LeftSupport=Read(Cell(r,"Left"),"the left support width",index)/1000,RightSupport=Read(Cell(r,"Right"),"the right support width",index)/1000,Slab=(Cell(r,"Slab")==""?0:Read(Cell(r,"Slab"),"the slab thickness",index))/1000,Quantity=qty,Include=!(r.Cells["Include"].Value is bool)||(bool)r.Cells["Include"].Value});}
  return list;}
 CutSettings Settings(){var name=Convert.ToString(config.SelectedItem);var cfg=CalculationStore.All().FirstOrDefault(c=>c.Name==name);if(cfg==null)throw new Exception("Choose a Splice, Development & Hooks configuration.");
  var lengths=stocks.Text.Split(new[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries).Select(t=>{double v;if(!double.TryParse(t,NumberStyles.Float,Inv,out v))throw new Exception("Commercial lengths: "+t+" is not a number.");return v;}).Distinct().OrderBy(v=>v).ToList();CommercialBars.Available(lengths);
  return new CutSettings{Config=cfg,SpecialMomentFrame=frame.SelectedIndex==0,Cover=(double)cover.Value,MaxBar=double.Parse(Convert.ToString(longest.SelectedItem),Inv),Stocks=lengths,EndZone=(double)endZone.Value/100,TieOffset=(double)offset.Value/1000,TopExtension=topExtension.SelectedIndex==0?1.0/3:.25};}
 internal void Calculate(){try{if(schedule.Count==0){status.Text="Load a beam schedule first.";return;}var input=SpanInputs();if(input.Count==0){status.Text="Enter the spans of each beam line.";Clear();return;}var s=Settings();
   BeamRow found;var result=BeamCutting.Build(input,m=>schedule.TryGetValue(m??"",out found)?found:null,s);last=result;lastSettings=s;lastSpans=input;Show(result);
   int ng=result.Splices.Count(c=>!c.Ok);status.ForeColor=result.Errors.Count+ng>0?Color.Firebrick:PowTheme.Teal;status.Text=(result.Errors.Count+ng>0?(result.Errors.Count+ng)+" item(s) to review - see the Review and Splice zone check tabs. ":"")+result.Pieces.Count+" cut groups, "+result.Splices.Count+" splices; included spans: rebar "+result.IncludedKg.ToString("N2")+" kg, concrete "+result.IncludedConcrete.ToString("N3")+" m3, forms "+result.IncludedFormwork.ToString("N2")+" m2.";}
  catch(Exception ex){status.ForeColor=Color.Firebrick;status.Text=ex.Message;}}
 void Clear(){foreach(var g in new[]{cutGrid,spliceGrid,estimateGrid,buyGrid}){g.Rows.Clear();g.Columns.Clear();}review.Text="";}
 static void Fill(DataGridView g,string[] headers,IEnumerable<object[]> rows){g.SuspendLayout();try{g.Rows.Clear();g.Columns.Clear();foreach(var h in headers)g.Columns.Add("c"+g.Columns.Count,h);foreach(var r in rows)g.Rows.Add(r);}finally{g.ResumeLayout();}}
 void Show(CutResult r){
  Fill(cutGrid,new[]{"BAR MARK","LOCATION","DIA (mm)","GRADE","CUT LENGTH (m)","PCS / LINE","LINES","TOTAL PCS","SHAPE","FROM (m)","TO (m)","WEIGHT (kg)"},r.Pieces.Select(p=>new object[]{p.BarMark,p.Location,p.Diameter,p.Grade,p.Length.ToString("0.000",Inv),p.PerLine,p.Lines,p.Pieces,p.Shape,p.Start.ToString("0.000",Inv),p.End.ToString("0.000",Inv),p.Kg.ToString("N2")}));
  Fill(spliceGrid,new[]{"LINE","BAR","DIA (mm)","SPAN","LAP FROM (m)","LAP TO (m)","LAP (m)","ALLOWED ZONE (m)","RESULT","NOTE"},r.Splices.Select(c=>new object[]{c.Line,c.Bar,c.Diameter,c.Span,c.From.ToString("0.000",Inv),c.To.ToString("0.000",Inv),c.Lap.ToString("0.000",Inv),c.ZoneFrom.ToString("0.000",Inv)+" - "+c.ZoneTo.ToString("0.000",Inv),c.Status,c.Note}));
  foreach(DataGridViewRow row in spliceGrid.Rows)if(Convert.ToString(row.Cells[8].Value)=="NG")row.DefaultCellStyle.ForeColor=Color.Firebrick;
  var dias=r.Spans.SelectMany(e=>e.KgByDiameter.Keys).Distinct().OrderBy(d=>d).ToList();
  Fill(estimateGrid,new[]{"LINE","SPAN","MARK","IN ESTIMATE","Ln (m)","IDENTICAL LINES"}.Concat(dias.Select(d=>d+" mm (kg)")).Concat(new[]{"REBAR (kg)","STIRRUP SETS","CONCRETE (m3)","FORMS (m2)"}).ToArray(),r.Spans.Select(e=>new object[]{e.Line,e.Span,e.Mark,e.Include?"Yes":"No",e.Ln.ToString("0.000",Inv),e.Quantity}.Concat(dias.Select(d=>{double v;return (object)(e.KgByDiameter.TryGetValue(d,out v)?v:0).ToString("N2");})).Concat(new object[]{e.Kg.ToString("N2"),e.Ties,e.Concrete.ToString("N3"),e.Formwork.ToString("N2")}).ToArray()).Concat(new[]{new object[]{"INCLUDED SPANS","","","","",""}.Concat(dias.Select(d=>(object)r.Spans.Where(e=>e.Include).Sum(e=>{double v;return e.KgByDiameter.TryGetValue(d,out v)?v:0;}).ToString("N2"))).Concat(new object[]{r.IncludedKg.ToString("N2"),r.Spans.Where(e=>e.Include).Sum(e=>e.Ties),r.IncludedConcrete.ToString("N3"),r.IncludedFormwork.ToString("N2")}).ToArray()}));
  foreach(DataGridViewRow row in estimateGrid.Rows)if(Convert.ToString(row.Cells[3].Value)=="No")row.DefaultCellStyle.ForeColor=Color.FromArgb(150,150,150);if(estimateGrid.Rows.Count>0)estimateGrid.Rows[estimateGrid.Rows.Count-1].DefaultCellStyle.Font=new Font(Font,FontStyle.Bold);
  Fill(buyGrid,new[]{"GRADE","DIA (mm)","CUT (m)","PIECES","STOCK LENGTH (m)","PCS / STOCK","BARS TO BUY","OFFCUT (m)"},r.Purchases.Select(p=>new object[]{p.Grade,p.Diameter,p.Cut.ToString("0.000",Inv),p.Pieces,p.Choice==null?"-":p.Choice.Length.ToString("0.##",Inv),p.Choice==null?"-":p.Choice.PiecesPerStock.ToString(Inv),p.Choice==null?"-":p.Choice.Bars.ToString(Inv),p.Choice==null?"-":p.Choice.Waste.ToString("0.00",Inv)}));
  review.Text=r.Errors.Count==0&&r.Splices.All(c=>c.Ok)?"No items to review.\r\n\r\n"+string.Join("\r\n",r.Notes):"REVIEW\r\n"+string.Join("\r\n",r.Errors.Select(e=>"- "+e).Concat(r.Splices.Where(c=>!c.Ok).Select(c=>"- "+c.Line+" "+c.Bar+" span "+c.Span+": "+c.Note)))+"\r\n\r\n"+string.Join("\r\n",r.Notes);}
 internal string ReportText(){if(last==null)throw new Exception("Nothing to report yet: load a schedule and enter the beam lines.");var info=ProjectReportHeader();return info+BeamCutting.Report(last,lastSettings,lastSpans);}
 static string ProjectReportHeader(){try{var p=ProjectInfoStore.Read();if(p==null||string.IsNullOrWhiteSpace(p.Name))return "";return p.NameLine+"\r\n"+p.LocationLine+"\r\n\r\n";}catch(Exception){return "";}}
 static string Tsv(DataGridView g){var b=new StringBuilder();b.AppendLine(string.Join("\t",g.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText)));foreach(DataGridViewRow r in g.Rows)b.AppendLine(string.Join("\t",r.Cells.Cast<DataGridViewCell>().Select(c=>Convert.ToString(c.Value,Inv))));return b.ToString();}
 /* project file */
 internal string ProjectXml(){var doc=new XmlDocument();var root=doc.CreateElement("BeamCuttingList");root.SetAttribute("version","1");root.SetAttribute("appVersion",Engine.Version);doc.AppendChild(root);
  root.SetAttribute("config",Convert.ToString(config.SelectedItem));root.SetAttribute("frame",frame.SelectedIndex.ToString(Inv));root.SetAttribute("cover",cover.Value.ToString(Inv));root.SetAttribute("longest",Convert.ToString(longest.SelectedItem));root.SetAttribute("stocks",stocks.Text);root.SetAttribute("endZone",endZone.Value.ToString(Inv));root.SetAttribute("offset",offset.Value.ToString(Inv));root.SetAttribute("topExtension",topExtension.SelectedIndex.ToString(Inv));
  foreach(var s in sources){var e=doc.CreateElement("Source");e.SetAttribute("name",s[1]);PowPackedText.Write(e,s[0]);root.AppendChild(e);}
  foreach(DataGridViewRow r in spans.Rows){if(r.IsNewRow)continue;var e=doc.CreateElement("Span");foreach(var c in new[]{"Line","Mark","Ln","Left","Right","Slab","Qty"})e.SetAttribute(c.ToLowerInvariant(),Cell(r,c));e.SetAttribute("include",(!(r.Cells["Include"].Value is bool)||(bool)r.Cells["Include"].Value).ToString());root.AppendChild(e);}
  return doc.OuterXml;}
 internal void OpenProjectXml(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=0}))doc.Load(reader);var root=doc.DocumentElement;if(root==null||root.Name!="BeamCuttingList"||root.GetAttribute("version")!="1")throw new Exception("This is not a beam cutting list file.");
  var files=root.SelectNodes("Source").Cast<XmlElement>().Select(e=>new[]{PowPackedText.Read(e),e.GetAttribute("name")}).ToList();filling=true;try{spans.Rows.Clear();if(files.Count>0)AddSources(files,true);else{sources.Clear();schedule.Clear();}
   if(config.Items.Contains(root.GetAttribute("config")))config.SelectedItem=root.GetAttribute("config");int f;if(int.TryParse(root.GetAttribute("frame"),out f)&&f>=0&&f<frame.Items.Count)frame.SelectedIndex=f;decimal v;if(decimal.TryParse(root.GetAttribute("cover"),NumberStyles.Float,Inv,out v))cover.Value=Math.Max(cover.Minimum,Math.Min(cover.Maximum,v));if(longest.Items.Contains(root.GetAttribute("longest")))longest.SelectedItem=root.GetAttribute("longest");if(root.HasAttribute("stocks"))stocks.Text=root.GetAttribute("stocks");if(decimal.TryParse(root.GetAttribute("endZone"),NumberStyles.Float,Inv,out v))endZone.Value=Math.Max(endZone.Minimum,Math.Min(endZone.Maximum,v));if(decimal.TryParse(root.GetAttribute("offset"),NumberStyles.Float,Inv,out v))offset.Value=Math.Max(offset.Minimum,Math.Min(offset.Maximum,v));if(int.TryParse(root.GetAttribute("topExtension"),out f)&&f>=0&&f<topExtension.Items.Count)topExtension.SelectedIndex=f;
   foreach(XmlElement e in root.SelectNodes("Span")){int i=spans.Rows.Add();var r=spans.Rows[i];foreach(var c in new[]{"Line","Ln","Left","Right","Slab","Qty"})r.Cells[c].Value=e.GetAttribute(c.ToLowerInvariant());string m=e.GetAttribute("mark");r.Cells["Mark"].Value=schedule.ContainsKey(m)?m:null;r.Cells["Include"].Value=e.GetAttribute("include")!="False";}}
  finally{filling=false;}Calculate();saved=State();}
 string State(){try{return ProjectXml();}catch(Exception){return "";}}
 bool SaveDialog(){if(schedule.Count==0)throw new Exception("Load a beam schedule first.");using(var d=new SaveFileDialog{Filter="Beam cutting list|*.beam-cutting.xml",FileName="Beam-Cutting-List.beam-cutting.xml"}){if(d.ShowDialog(this)!=DialogResult.OK)return false;string xml=ProjectXml();string temp=d.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,xml,new UTF8Encoding(false));File.Copy(temp,d.FileName,true);}finally{if(File.Exists(temp))File.Delete(temp);}saved=xml;status.ForeColor=PowTheme.Teal;status.Text="Saved "+Path.GetFileName(d.FileName)+".";return true;}}
 void Save(){SaveDialog();}
 void Open(){using(var d=new OpenFileDialog{Filter="Beam cutting list|*.beam-cutting.xml"})if(d.ShowDialog(this)==DialogResult.OK)OpenProjectXml(File.ReadAllText(d.FileName));}
}
}
